    #[ignore = "red prerequisite: actual natural reset/continuation not yet ported"]
    fn published_member_natural_default_reset_requires_native_continuation() {
        let source="class BaseType<T> { bar:T } class NextType<C extends {someProp:any},T=C['someProp']> extends BaseType<T> { baz:string } class Foo extends NextType<Foo> { someProp:{test:true} } const foo=new Foo(); const probe=foo.bar.test;";
        let mut missing=Vec::new();
        for order in 0..3 {
            with_checker(source,|checker,root| {
                checker.apply_compiler_options(&tsr_core::CompilerOptions {strict:tsr_core::Tristate::False,target:tsr_core::ScriptTarget::ES2020,..tsr_core::CompilerOptions::default()});
                let foo=checker.binder.lookup_local(root,"Foo").unwrap();
                if order==1 { let probe=checker.binder.lookup_local(root,"probe").unwrap();checker.get_type_of_symbol(probe); }
                if order==2 { checker.check_source_file(root,crate::check::FileContext {ambient:false,has_parse_errors:false}); }
                let ty=checker.get_declared_type_of_symbol(foo);
                let _=publication(checker,ty,"someProp");
                let entries:Vec<_>=checker.member_publication.member_entries.iter().filter(|(owner,_)| *owner==foo).cloned().collect();
                let resets:Vec<_>=checker.member_publication.target_resets.iter().filter(|(owner,_,_,_)| *owner==foo).cloned().collect();
                checker.check_source_file(root,crate::check::FileContext {ambient:false,has_parse_errors:false});
                let codes:Vec<_>=checker.diagnostics.iter().map(|(_,d)| d.message.code()).collect();
                println!("NATURAL_DEFAULT order={order} entries={entries:?} resets={resets:?} diagnostic_codes={codes:?}");
                // Existing native .30 producer observes actual partial publication,
                // reset, then either a fresh worker or continuing outer completion.
                // A property-only false done bit is not that certificate.
                // Record property-only state without relabeling it as native
                // MembersResolved. The full member-field certificate is absent.
                if !codes.contains(&2310) { missing.push(order); }
            });
        }
        assert!(missing.is_empty(),"native circular/default TS2310 missing in orders {missing:?}; natural full-member continuation remains unqualified");
